      {
        "dayTitle": "Day 1: Arrival in Las Vegas & Drive to Springdale (Zion National Park)",
        "icon": "../assets/r_000850_01_2_car-front.svg",
        "morning": "Arrive at Harry Reid International Airport (LAS) in Las Vegas, pick up your rental car.",
        "routeDrive": "Drive approximately 2.5-3 hours north on I-15 N to Springdale, the gateway town to Zion National Park.",
        "afternoon": "Check into your accommodation in Springdale. Take some time to relax by the Virgin River or explore the town's shops.",
        "scenicStop": "Enjoy the changing desert landscape as you drive, particularly the Virgin River Gorge just after entering Arizona.",
        "lightHike": "A gentle stroll along the Pa'rus Trail near the park entrance (you can do a short section today or save for Day 3).",
        "food": "Casual dinner in Springdale, offering various family-friendly options.",
        "overnightStay": "Springdale, Utah.",
        "actionLabel": "Explore Springdale Lodging",
        "actionUrl": "https://www.nps.gov/zion/planyourvisit/lodging.htm"
      },
      {
        "dayTitle": "Day 2: Zion National Park - Emerald Pools & Canyon Views",
        "icon": "../assets/r_000850_01_4_tree.svg",
        "morning": "Take the free park shuttle into Zion Canyon. Hike the Lower and Middle Emerald Pools Trails (easy to moderate, ~2-3 miles round trip). Kids will enjoy the waterfalls and lush greenery.",
        "routeDrive": "Utilize the park's scenic shuttle system to navigate Zion Canyon. Private vehicles are generally not allowed on the main scenic drive during peak season.",
        "afternoon": "Continue on the shuttle to explore other viewpoints like Weeping Rock (currently closed for repairs, check NPS website for updates) or Big Bend. Enjoy a picnic lunch by the Virgin River.",
        "scenicStop": "The entire Zion Canyon Scenic Drive offers breathtaking views of the towering sandstone cliffs. The shuttle allows everyone to take in the scenery.",
        "lightHike": "The Emerald Pools Trails are perfect for the family. Consider the Riverside Walk (easy, paved, leads to the Narrows entrance) in the late afternoon.",
        "food": "Pack a picnic lunch to enjoy inside the park. Dinner in Springdale.",
        "overnightStay": "Springdale, Utah.",
        "actionLabel": "Zion Shuttle Info",
        "actionUrl": "https://www.nps.gov/zion/planyourvisit/zion-canyon-shuttle-system.htm"
      },
      {
        "dayTitle": "Day 3: Pa'rus Trail & Drive to Bryce Canyon National Park",
        "icon": "../assets/r_000850_01_6_signpost-split.svg",
        "morning": "Enjoy a leisurely morning. Walk the full Pa'rus Trail (easy, paved, 3.5 miles round trip) from the Visitor Center, suitable for all ages and even strollers. It follows the Virgin River and offers beautiful riverside views.",
        "routeDrive": "Depart Springdale and drive east on UT-9 (Zion-Mount Carmel Highway), through the famous Zion-Mount Carmel Tunnel, then north on US-89, and finally east on UT-12 to Bryce Canyon National Park. This drive is approximately 1.5-2 hours.",
        "afternoon": "Arrive at Bryce Canyon City or Tropic, check into your lodging.",
        "scenicStop": "The drive on UT-9 through Zion's east side offers incredible, often less crowded, views. Don't miss the Checkerboard Mesa.",
        "lightHike": "The Pa'rus Trail.",
        "food": "Lunch in Springdale or a packed lunch for the drive. Dinner in Bryce Canyon City.",
        "overnightStay": "Bryce Canyon City or Tropic, Utah.",
        "actionLabel": "Bryce Canyon Lodging",
        "actionUrl": "https://www.nps.gov/brca/planyourvisit/lodging.htm"
      },
      {
        "dayTitle": "Day 4: Bryce Canyon National Park - Hoodoos & Rim Trail",
        "icon": "../assets/r_000850_01_8_geo-alt.svg",
        "morning": "Head into Bryce Canyon National Park. Hike the iconic Navajo Loop and Queen's Garden Trail combination (moderate, ~3 miles, 600 ft elevation change",
